{"content": "1|// Enforces the size budget of the shipped game (index.html + src/**).
2|// Usage: node tools/size-check.mjs     Exit code 1 when over budget.
3|import { readdirSync, readFileSync, statSync } from 'node:fs';
4|import { join, relative, resolve } from 'node:path';
5|import { gzipSync } from 'node:zlib';
6|import { fileURLToPath } from 'node:url';
7|
8|// MVP uses ~52 KB raw / ~19 KB gzip. The headroom is for candidates' features.
9|export const BUDGET = { raw: 96 * 1024, gzip: 32 * 1024 };
10|
11|const ROOT = resolve(fileURLToPath(new URL('..', import.meta.url)));
12|const walk = (dir) => readdirSync(dir).flatMap((f) => {
13|  const p = join(dir, f);
14|  return statSync(p).isDirectory() ? walk(p) : [p];
15|});
16|
17|const files = [join(ROOT, 'index.html'), ...walk(join(ROOT, 'src'))];
18|const all = Buffer.concat(files.map((f) => readFileSync(f)));
19|const raw = all.length, gzip = gzipSync(all, { level: 9 }).length;
20|
21|const kb = (n) => `${(n / 1024).toFixed(1)} KB`;
22|for (const f of files) console.log(`${kb(statSync(f).size).padStart(9)}  ${relative(ROOT, f).replaceAll('\\', '/')}`);
23|console.log('-'.repeat(40));
24|console.log(`${kb(raw).padStart(9)}  total raw   (budget ${kb(BUDGET.raw)})`);
25|console.log(`${kb(gzip).padStart(9)}  total gzip  (budget ${kb(BUDGET.gzip)})`);
26|
27|if (raw > BUDGET.raw || gzip > BUDGET.gzip) {
28|  console.error('\nSize budget exceeded. Generate it, don\'t ship it.');
29|  process.exit(1);
30|}
