+const HANDSHAKE = (key = 'dGhlIHNhbXBsZSBub25jZQ==', version = '13') =>
+  `GET /ws HTTP/1.1\r\nHost: localhost\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n` +
